"""
Ajoute au warehouse (data/warehouse.seed.json) le registre consolidé de la
contribution du secteur extractif à l'économie — production, exportations
et emploi ventilé par genre (Exigence ITIE 6.3, volet formel) — à partir du
fichier fourni par l'utilisateur « ITIE_RDC_Contribution_economie_6.3.xlsx »,
lui-même construit à partir des Annexes 15/17 (production), 16/18
(exportations) et 42/55 (emploi) des Rapports ITIE-RDC 2022 et 2023.

Ce fichier ne couvre que le volet formel de l'Exigence 6.3 ; le volet
informel (artisanat minier / EMAPE) est couvert séparément par le script
build_emape_artisanat_6_3.py et le thème reste marqué, dans son propre jeu
de données de vue d'ensemble, comme incomplet sur la contribution au PIB et
sur l'économie extractive informelle — un point explicitement relevé par la
Validation ITIE-RDC.

Principe (« ne rien cacher ») : les valeurs sont reprises telles quelles,
y compris les cellules vides (indicateur non déclaré par la société pour
cet exercice) qui restent vides plutôt que d'être complétées.
"""
from __future__ import annotations

import json
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent.parent
WAREHOUSE_PATH = BASE_DIR / "data" / "warehouse.seed.json"

SOURCE_XLSX = (
    "« ITIE_RDC_Contribution_economie_6.3.xlsx », fourni directement par "
    "l'utilisateur (2026-09-24) — registre consolidé, société par société, "
    "des Annexes 15/17 (production), 16/18 (exportations) et 42/55 (emploi "
    "ventilé par genre) des Rapports ITIE-RDC 2022 et 2023, au titre de "
    "l'Exigence ITIE 6.3 (contribution du secteur extractif à l'économie)."
)

THEME_KEY = "contribution_eco"

COMMON_META = dict(
    theme=THEME_KEY,
    theme_label="Contribution économique du secteur",
    source=SOURCE_XLSX,
    periode="2022-2023",
)

DATASETS: dict = {}


def add(name, label, cat, desc, cols, types, rows, **meta_over):
    meta = dict(COMMON_META)
    meta.update(meta_over)
    DATASETS[name] = dict(label=label, cat=cat, desc=desc, cols=cols, types=types, rows=rows, meta=meta)


